{"input":{"new":"/// Display lint results and exit with the appropriate code.
///
/// Exit code is determined by the `--fail-on` threshold (Issue #209 Bug 1):
/// the previous version unconditionally exited 1 on warnings, so passing
/// `--fail-on error` could not raise the threshold above warnings.
pub(crate) fn output_lint_results(
    result: &crate::linter::LintResult,
    format: LintFormat,
    input: &Path,
    fail_on: LintLevel,
) -> Result<()> {
    use crate::linter::output::write_results;

    let output_format = super::convert_lint_format(format);
    let file_path = input.to_str().unwrap_or("unknown");
    write_results(&mut std::io::stdout(), result, output_format, file_path)
        .map_err(|e| Error::Internal(format!("Failed to write lint results: {e}")))?;

    // Decide exit code from the --fail-on threshold.
    // Exit 0: below threshold
    // Exit 1: at threshold (warning-level fail)
    // Exit 2: errors present and threshold reached
    let should_fail = match fail_on {
        LintLevel::Error => result.has_errors(),
        LintLevel::Warning => result.has_errors() || result.has_warnings(),
        LintLevel::Info => !result.diagnostics.is_empty(),
    };

    if should_fail {
        if result.has_errors() {
            std::process::exit(2);
        } else {
            std::process::exit(1);
        }
    }

    Ok(())
